require "rails_helper"

RSpec.describe Timekeeping::Handoff::ServiceStore do
  include_context "timekeeping entry writes without transactional fixtures"

  # Issue: "Advance sequence: set the `entries` id sequence above a given id
  # "only if the new value is higher than its current one"."
  it "service store advances the entry id sequence only forward and new entries get ids above the highest target" do
    store = described_class.new(connection: ApplicationRecord.connection)

    expect(store.advance_entry_id_sequence(above: 100)).to eq(101)
    expect(store.advance_entry_id_sequence(above: 10)).to eq(101)
    expect(store.advance_entry_id_sequence(above: 100)).to eq(101)

    now = Time.utc(2026, 3, 2, 9)
    entry = Entry.create!(company_id: 1, project_id: 5, user_id: 6, work_date: Date.new(2026, 3, 2), duration: 30.0,
                          bill_status: "unbilled", created_at: now, updated_at: now)
    expect(entry.id).to be > 100
  end

  describe "export and load" do
    let(:store) { described_class.new(connection: ApplicationRecord.connection) }
    let(:service_store_at) { Time.utc(2026, 3, 1, 12, 30, 15.123456r) }

    # The values this spec's examples depend on, laid over the shared builder:
    # jsonb decimals finer than a Float, a JSON null, a fractional timestamp,
    # and audit, receipt and operation ids (400, 500, 300) the sequence
    # examples compare against.
    def service_store_overrides(version: 2)
      at = service_store_at
      {
        "entries" => { "version" => version, "project_id" => 11, "user_id" => 12, "duration" => 90.25,
                       "note" => "Loaded", "created_at" => at, "updated_at" => at,
                       "source_metadata" => { "amount" => BigDecimal("1.00000000000000000001"),
                                              "nested" => { "a" => [1, nil] } } },
        "reservations" => { "invoice_id" => 41, "operation_id" => "11111111-1111-4111-8111-111111111111",
                            "created_at" => at, "invoice_operation_id" => nil },
        "invoice_operations" => { "id" => 300, "invoice_id" => 41,
                                  "operation_id" => "22222222-2222-4222-8222-222222222222", "state" => "aborted",
                                  "desired_entry_ids" => [900, 901], "disposition" => "retained",
                                  "generation" => 2, "created_at" => at, "finished_at" => nil },
        "entry_audits" => { "id" => 400, "actor_id" => 12, "action" => "update", "entry_created_at" => at,
                            "created_at" => at,
                            "after" => { "duration" => BigDecimal("0.1000000000000000000001") } },
        "idempotency_records" => { "id" => 500, "actor_id" => 12, "key" => "key-1", "fingerprint" => "abc",
                                   "body" => "{\"id\":900}", "created_at" => at }
      }
    end

    def service_store_entry_row(id:, company_id:, version: 2)
      handoff_checkpoint_tables(company_id:, id:, overrides: service_store_overrides(version:)).fetch("entries").first
    end

    # Two companies: both own an entry; company 8 holds the reservation,
    # audit and service receipt, company 9 the invoice operation and receipt.
    def service_store_tables
      eight = handoff_checkpoint_tables(company_id: 8, id: 900, overrides: service_store_overrides)
      nine = handoff_checkpoint_tables(company_id: 9, id: 901, overrides: service_store_overrides)
      {
        "entries" => eight.fetch("entries") + nine.fetch("entries"),
        "reservations" => eight.fetch("reservations"),
        "invoice_operations" => nine.fetch("invoice_operations"),
        "entry_audits" => eight.fetch("entry_audits"),
        "idempotency_records" => nine.fetch("idempotency_records"),
        "service_idempotency_receipts" => eight.fetch("service_idempotency_receipts")
      }
    end

    def service_store_checkpoint
      Timekeeping::Handoff::Checkpoint.build(tables: service_store_tables)
    end

    def service_store_snapshot
      { entries: Entry.order(:company_id, :id).pluck(:company_id, :id, :version, :note),
        reservations: Reservation.count, invoice_operations: InvoiceOperation.pluck(:id),
        audit_events: AuditEvent.pluck(:id), idempotency_receipts: IdempotencyReceipt.pluck(:id),
        service_idempotency_receipts: ServiceIdempotencyReceipt.pluck(:id) }
    end

    def service_store_seed_prior_rows
      entry = Entry.create!(company_id: 7, project_id: 2, user_id: 1, work_date: Date.new(2026, 3, 2), duration: 30.0,
                            version: 3, note: "Kept", bill_status: "unbilled")
      AuditEvent.create!(company_id: 7, entry_id: entry.id, actor_type: "user", actor_id: 1, action: "create",
                         after: { "note" => "Kept" }, entry_created_at: entry.created_at, created_at: Time.current)
      entry
    end

    # Each refused load is compared to the one baseline taken before the table,
    # so a refusal that changed rows and a later one that put them back cannot
    # pass together.
    it "refuses a load while admitted, with an edited body or with an older entry version, and changes nothing" do
      stored = service_store_seed_prior_rows
      before = service_store_snapshot
      expect(before.slice(:entries, :reservations, :invoice_operations, :idempotency_receipts))
        .to eq(entries: [[7, stored.id, 3, "Kept"]], reservations: 0, invoice_operations: [], idempotency_receipts: [])
      expect(before.fetch(:audit_events).size).to eq(1)

      tampered_document = JSON.parse(service_store_checkpoint.to_json)
      note = tampered_document.fetch("tables").fetch("entries").first.find { |column, _| column == "note" }
      note[1] = ["str", "Tampered"]
      older_checkpoint = Timekeeping::Handoff::Checkpoint.build(tables: service_store_tables.merge(
        "entries" => [service_store_entry_row(id: stored.id, company_id: 7, version: 2)],
        "reservations" => [], "entry_audits" => []
      ))
      # Rows run in order: the first needs writes admitted, the rest a fence.
      refusals = [
        ["writes admitted", service_store_checkpoint, /fence admission first/],
        ["edited after its digest", Timekeeping::Handoff::Checkpoint.from_json(JSON.generate(tampered_document)), /digest/],
        ["older entry version", older_checkpoint, /newer entry versions/]
      ]

      refusals.each do |name, checkpoint, reason|
        Timekeeping::Admission.fence! unless name == "writes admitted"

        expect { store.load_checkpoint(checkpoint) }.to raise_error(Timekeeping::Handoff::Store::Error, reason)
        expect([name, service_store_snapshot]).to eq([name, before])
      end
    end

    # "Load: "replaces the incoming owner's tables in one transaction", so loading
    # the same checkpoint twice gives equal counts and checksums."
    # Two committed reservations for one entry break a unique index only after the
    # entries were deleted and re-inserted, so a load that is not one transaction
    # would leave the stored entry gone.
    it "rolls the whole load back when an insert fails after entries were already replaced" do
      kept = service_store_seed_prior_rows
      Timekeeping::Admission.fence!
      tables = handoff_checkpoint_tables(company_id: 8, id: 500)
      tables["reservations"] << tables.fetch("reservations").first.merge("invoice_id" => 42,
                                                                         "operation_id" => SecureRandom.uuid)

      expect { store.load_checkpoint(Timekeeping::Handoff::Checkpoint.build(tables:)) }
        .to raise_error(Timekeeping::Handoff::Store::Error)
      expect(Entry.pluck(:id, :company_id, :note)).to eq([[kept.id, 7, "Kept"]])
      expect(AuditEvent.where(entry_id: kept.id).count).to eq(1)
      expect([Reservation.count, InvoiceOperation.count, IdempotencyReceipt.count]).to eq([0, 0, 0])
    end

    # "Every row carries `company_id`."
    it "exports all five checkpoint tables including invoice_operations, every row with its company_id" do
      now = Time.utc(2026, 3, 2, 9)
      Entry.create!(id: 71, company_id: 8, version: 1, project_id: 5, user_id: 7, work_date: Date.new(2026, 3, 2),
                    duration: 15.0, note: "", bill_status: "unbilled", created_at: now, updated_at: now)
      InvoiceOperation.create!(company_id: 8, invoice_id: 3, operation_id: SecureRandom.uuid,
                               actor_name: "invoice-service", state: "committed", desired_entry_ids: [71],
                               disposition: "active", generation: 2, created_at: now, finished_at: now)

      checkpoint = store.export_checkpoint

      expect(checkpoint.rows.keys).to match_array(Timekeeping::Handoff::Checkpoint::TABLES.keys)
      expect(checkpoint.rows.fetch("invoice_operations").map { |row| [row["company_id"], row["desired_entry_ids"]] })
        .to eq([[8, [71]]])
      expect(checkpoint.rows.values.flatten.pluck("company_id")).to all(eq(8))
    end

    it "loads two companies' rows and exports them unchanged, and a second load gives the same result" do
      Timekeeping::Admission.fence!
      checkpoint = service_store_checkpoint

      first = store.load_checkpoint(checkpoint)
      first_rows = service_store_snapshot
      second = store.load_checkpoint(checkpoint)
      exported = store.export_checkpoint

      expect([first.digest, second.digest, exported.digest]).to all(eq(checkpoint.digest))
      expect(service_store_snapshot).to eq(first_rows)
      expect(exported.rows.fetch("entry_audits").first.fetch("before")).to be(Timekeeping::Handoff::Checkpoint::JSON_NULL)
      expect(exported.rows.fetch("invoice_operations").first.values_at("desired_entry_ids", "finished_at"))
        .to eq([[900, 901], nil])
      expect(exported.rows.fetch("entries").pluck("company_id")).to eq([8, 9])
    end

    it "leaves outbox_snapshots and the admission row untouched by a load" do
      entry = service_store_seed_prior_rows
      OutboxSnapshot.insert_all!([entry.reload.attributes.slice(*Timekeeping::OutboxFields::ENTRY_FIELDS)
                                       .merge("locked" => false, "generation" => 1)])
      Timekeeping::Admission.fence!
      outbox_before = OutboxSnapshot.pluck(:outbox_position, :company_id, :id)

      store.load_checkpoint(service_store_checkpoint)

      expect(OutboxSnapshot.pluck(:outbox_position, :company_id, :id)).to eq(outbox_before)
      expect(Timekeeping::Admission.current.generation).to be_nil
      expect(store.highest_outbox_position).to eq(outbox_before.map(&:first).max)
    end

    it "moves the audit and receipt id sequences above the loaded ids" do
      Timekeeping::Admission.fence!
      store.load_checkpoint(service_store_checkpoint)

      audit = AuditEvent.create!(company_id: 8, entry_id: 900, actor_type: "user", actor_id: 1, action: "update",
                                 after: {}, entry_created_at: Time.current, created_at: Time.current)
      expect(audit.id).to be > 400
      receipt = IdempotencyReceipt.create!(company_id: 9, actor_type: "user", actor_id: 12, operation: "create",
                                           key: "key-after-load", fingerprint: "def", status: 201, body: "{}",
                                           created_at: Time.current)
      expect(receipt.id).to be > 500
      operation = InvoiceOperation.create!(company_id: 9, invoice_id: 42, operation_id: SecureRandom.uuid, actor_name: "invoice-service",
                                           state: "committed", disposition: "active", generation: 2,
                                           created_at: Time.current)
      expect(operation.id).to be > 300
    end

    it "never moves the audit, receipt and operation id sequences back when a checkpoint holds lower ids" do
      Timekeeping::Admission.fence!
      store.load_checkpoint(service_store_checkpoint)
      lower = service_store_tables
      lower.fetch("invoice_operations").first["id"] = 3
      lower.fetch("entry_audits").first["id"] = 4
      lower.fetch("idempotency_records").first["id"] = 5
      lower.fetch("service_idempotency_receipts").first["id"] = 6
      store.load_checkpoint(Timekeeping::Handoff::Checkpoint.build(tables: lower))

      next_ids = %w[invoice_operations audit_events idempotency_receipts service_idempotency_receipts]
        .index_with { |table| handoff_next_id(table) }
      expect(next_ids).to eq("invoice_operations" => 301, "audit_events" => 401, "idempotency_receipts" => 501,
                             "service_idempotency_receipts" => 901)
    end

    it "refuses to export while a prepared invoice operation remains" do
      InvoiceOperation.create!(company_id: 8, invoice_id: 3, operation_id: SecureRandom.uuid, actor_name: "invoice-service",
                               state: "prepared",
                               disposition: "active", generation: 2, created_at: Time.current)

      expect { store.export_checkpoint }.to raise_error(Timekeeping::Handoff::Store::Error, /prepared operations/)
    end
  end

  # Generated by Descant: acceptance tests below.

  # "Replay the stored answer: the operation row for prepare, the receipt for the other operations."
  # A service receipt that does not cross a cutover lets a retried detach_entries run a second time
  # after the handoff, so the checkpoint must carry these rows in both directions.
  it "service store carries service idempotency receipts through export and load unchanged and moves their id sequence above the loaded ids" do
    store = described_class.new(connection: ApplicationRecord.connection)
    at = Time.utc(2026, 3, 2, 9, 15, 30.123456r)
    ServiceIdempotencyReceipt.create!(id: 700, company_id: 8, actor_name: "agent-destroy", operation: "detach_entries 77",
                                      key: "33333333-3333-4333-8333-333333333333", fingerprint: "f1", status: 200,
                                      body: "{\"detached\":2}", created_at: at)
    ServiceIdempotencyReceipt.create!(id: 701, company_id: 9, actor_name: "invoice-boundary", operation: "commit",
                                      key: "33333333-3333-4333-8333-333333333333", fingerprint: "f2", status: 200,
                                      body: "{\"reserved\":1,\"released\":0}", created_at: at)
    stored = lambda do
      ServiceIdempotencyReceipt.order(:id)
        .pluck(:id, :company_id, :actor_name, :operation, :key, :fingerprint, :status, :body, :created_at)
    end
    before = stored.call

    checkpoint = store.export_checkpoint
    expect(checkpoint.rows.fetch("service_idempotency_receipts").map { |row| [row["id"], row["company_id"], row["actor_name"]] })
      .to eq([[700, 8, "agent-destroy"], [701, 9, "invoice-boundary"]])

    ServiceIdempotencyReceipt.delete_all
    Timekeeping::Admission.fence!
    loaded = store.load_checkpoint(checkpoint)

    expect(loaded.digest).to eq(checkpoint.digest)
    expect(stored.call).to eq(before)
    expect(store.export_checkpoint.digest).to eq(checkpoint.digest)
    later = ServiceIdempotencyReceipt.create!(company_id: 8, actor_name: "agent-destroy", operation: "detach_entries 78",
                                              key: SecureRandom.uuid, fingerprint: "f3", status: 200, body: "{}",
                                              created_at: Time.current)
    expect(later.id).to be > 701
  end
end
